diff --git a/scripts/check-engines.mjs b/scripts/check-engines.mjs
index ce51156..07e924d 100644
--- a/scripts/check-engines.mjs
+++ b/scripts/check-engines.mjs
@@ -5,6 +5,20 @@ const declared = pkg.engines?.node ?? "";
 const floor = Number(declared.replace(/[^0-9]/g, "").slice(0, 2));

 if (!Number.isInteger(floor) || floor < 22) {
-  console.error(`engines.node is "${declared}" — the floor may not go below 22`);
+  const current = process.versions.node;
+  console.error(`
+ERROR: Node.js ${current} is not supported. This package requires Node.js ${declared}.
+
+Why? Node.js versions older than 22 are no longer receiving security updates.
+This package enforces a secure runtime to protect your system.
+
+How to upgrade:
+  • nvm:   nvm install 22
+  • fnm:   fnm install 22
+  • macOS: brew install node@22
+  • Other: https://nodejs.org/en/download/
+
+For details, see: https://nodejs.org/en/about/previous-releases/
+`);
   process.exit(1);
 }
